static void run_case(const ActualRow* rows,unsigned n) {
    for(unsigned tab=1;tab<alden::TabCount;++tab) {
        fixture::setup();std::vector<alden::Ptr> expected;
        for(unsigned i=0;i<n;++i) {
            const auto row=rows[i];
            put(reinterpret_cast<alden::Ptr>(fixture::items[i].data())+8,row.item);
            const auto rec=reinterpret_cast<alden::Ptr>(fixture::records[i].data());
            put(rec+0x28,row.purchase);put(rec+0x2c,row.stable);
            alden::Row input{rec,row.item,row.stable};
            check(alden::category(input)!=255,"actual stock identity recognized");
            if(alden::category(input)==tab) expected.push_back(rec);
        }
        put(fixture::s()+0x188,n);alden::states[0].tab=tab;
        alden::count_hook(fixture::s(),n);
        check(!alden::states[0].fault,"actual sparse purchase/stable identity layout accepted");
        check(get<unsigned>(fixture::s()+0x188)==expected.size(),"actual catalog category count");
        for(unsigned i=0;i<expected.size();++i) check(fixture::pointers[i]==expected[i],"actual purchase record order");
        for(unsigned i=0;i<n;++i) {
            const auto rec=reinterpret_cast<alden::Ptr>(fixture::records[i].data());
            check(get<unsigned>(rec+0x28)==rows[i].purchase,"compact native purchase position untouched");
            check(get<unsigned>(rec+0x2c)==rows[i].stable,"persistent stock identity untouched");
        }
    }
}
int main() {
    previous_tests_main();
    run_case(Rows0,840u);std::puts("PASS: current full catalog; every category; compact purchase and persistent stock identities preserved.");
    run_case(Rows1,839u);std::puts("PASS: captured live 839-row shop; every category; compact purchase and persistent stock identities preserved.");
    return 0;
}
